def _validate_request(data, signature):
    """Validate the payload and authenticate the request.

    Payload validation is kept separate from request processing so invalid
    requests cannot reach ``process``.  Signature verification is mandatory
    for every request.
    """
    if data is None:
        raise ValueError("request data is required")
    if signature is None:
        raise PermissionError("request signature is required")
    if not verify_signature(data, signature):
        raise PermissionError("invalid signature")


def handle_request(data, signature):
    """Validate and process a request payload."""
    _validate_request(data, signature)
    return process(data)

